      const hue=h=>{h=((h%1+1)%1)*6;const x=1-Math.abs(h%2-1);return [[1,x,0],[x,1,0],[0,1,x],[0,x,1],[x,0,1],[1,0,x]][Math.floor(h)%6].map(v=>v*255);};
