    _activityMarkup(speakerId){const journal=!speakerId&&!this._utility,speaker=journal?this._journalSpeaker:speakerId,query=journal?(this._journalQuery??'').trim().toLowerCase():'',all=(this._events??[]).filter(e=>(!speaker||e.speaker_id===speaker)&&(!query||(e.text??'').toLowerCase().includes(query))).slice(0,100);this._activityPage=Math.max(0,Math.min(this._activityPage,Math.max(0,Math.ceil(all.length/20)-1)));const start=this._activityPage*20,events=all.slice(start,start+20),tone=e=>e.error||['error','failed','unavailable'].includes(e.status)?'bad':['clarification','pending','cancelled'].includes(e.status)?'warn':'ok';return `${this._activityError?'<p class="help error" role="status">Не удалось загрузить журнал.</p>':''}${events.length?`<ul class="events list">${events.map(e=>`<li class="ev"><span class="dot ${tone(e)}"></span><div><strong>${escape(e.text||'Команда без текста')}</strong><p>${escape(this._statusLabel(e.status))} · ${escape(this._routeLabel(e.route))}${e.source?' · '+escape(this._sourceLabel(e.source)):''}${e.calls?.length?' · '+e.calls.map(c=>escape(c.label??c.target??c.name??'Действие')).join(', '):''}</p>${e.error?`<p class="error">${escape(e.error)}</p>`:''}<p>${escape(this._speakers.find(s=>s.id===e.speaker_id)?.name??e.speaker_id??'Колонка не указана')} · ${escape(this._eventTime(e.at))}${Number.isFinite(e.duration_ms)?' · '+e.duration_ms+' мс':''}</p></div>${this._executor(e)}</li>`).join('')}</ul>${all.length>20?`<div class="pager"><span>${start+1}–${start+events.length} из ${all.length}</span><div class="actions"><button type="button" data-action="activity-prev" ${start===0?'disabled':''}>Новее</button><button type="button" data-action="activity-next" ${start+20>=all.length?'disabled':''}>Раньше</button></div></div>`:''}`:'<p class="help">Событий пока нет.</p>'}`;}
    _eventTime(at){if(!at)return 'Время не указано';const date=new Date(typeof at==='number'&&at<1e12?at*1000:at);return Number.isNaN(date.getTime())?'Время не указано':date.toLocaleString('ru-RU');}
